"""
4-colouring of complete graphs without monochromatic triangles.
Uses the Greenwood-Gleason construction over GF(16) to get K_32,
then attempts to extend to K_33 via backtracking CSP.
"""
import time

def construct():
    start_time = time.time()
    deadline = start_time + 110.0

    # GF(16) arithmetic: field generated by x^4 + x + 1 (primitive polynomial)
    # Elements are 4-bit integers 0..15.
    # Multiplication in GF(16):
    def gf16_mul(a, b):
        r = 0
        for i in range(4):
            if (b >> i) & 1:
                r ^= a << i
        # Reduce modulo x^4 + x + 1 = 0b10011
        for i in range(7, 3, -1):
            if (r >> i) & 1:
                r ^= 0b10011 << (i - 4)
        return r

    # Build log table: log[x] = e such that 2^e = x (with 2 as primitive element)
    log = {}
    x = 1
    for e in range(15):
        log[x] = e
        x = gf16_mul(x, 2)

    # Base K32 coloring: two copies of K16, edges within each copy colored by
    # cubic-residue classes mod 3 of the GF(16) log, edges between copies get color 3.
    colors = []
    for i in range(32):
        for j in range(i + 1, 32):
            if i // 16 == j // 16:
                # Same copy: color by log[i^j] % 3
                colors.append(log[i ^ j] % 3)
            else:
                # Different copies: color 3
                colors.append(3)

    # Build adjacency lists for the three color classes within one copy of K16
    adj = [[set() for _ in range(3)] for _ in range(16)]
    for i in range(16):
        for j in range(i + 1, 16):
            c = log[i ^ j] % 3
            adj[i][c].add(j)
            adj[j][c].add(i)

    # Attempt to extend to K33 by adding vertex 32.
    # Vertex 32 connects to vertices 0..15 (copy 1) with colors from {0,1,2}
    # and to vertices 16..31 (copy 2) with colors from {0,1,2,3}.
    # For copy 1: if vertex 32 has color c to vertex u, then it cannot have
    # color c to any neighbor of u in G_c.
    # For copy 2: similar, plus color 3 is always valid (no G_3 within a copy).

    def solve_csp(n_vars, adj_list, allowed_colors, deadline):
        """Backtracking CSP solver.
        n_vars: number of variables
        adj_list: adj_list[v][c] = set of neighbors of v in color class c
        allowed_colors[v]: list of colors allowed for variable v
        """
        assignment = [-1] * n_vars
        # Order by most constrained first (fewest allowed colors)
        order = list(range(n_vars))
        order.sort(key=lambda v: len(allowed_colors[v]))

        def backtrack(idx):
            if time.time() > deadline:
                return None
            if idx == n_vars:
                return assignment[:]
            v = order[idx]
            for c in allowed_colors[v]:
                # Check constraints with already-assigned variables
                valid = True
                for prev_idx in range(idx):
                    u = order[prev_idx]
                    if assignment[u] == c:
                        if v in adj_list[u][c]:
                            valid = False
                            break
                if valid:
                    assignment[v] = c
                    res = backtrack(idx + 1)
                    if res is not None:
                        return res
                    assignment[v] = -1
            return None

        return backtrack(0)

    # Solve for copy 1 (vertices 0..15): colors in {0,1,2}
    allowed_c1 = [[0, 1, 2]] * 16
    sol_c1 = solve_csp(16, adj, allowed_c1, deadline)

    if sol_c1 is None:
        return {'n': 32, 'colors': colors}

    # Solve for copy 2 (vertices 16..31): colors in {0,1,2,3}
    # adj_list for copy 2 is the same as copy 1 (isomorphic), but color 3 has no adjacency
    adj_c2 = [[set() for _ in range(4)] for _ in range(16)]
    for i in range(16):
        for c in range(3):
            adj_c2[i][c] = adj[i][c]
        adj_c2[i][3] = set()

    allowed_c2 = [[0, 1, 2, 3]] * 16
    sol_c2 = solve_csp(16, adj_c2, allowed_c2, deadline)

    if sol_c2 is None:
        return {'n': 32, 'colors': colors}

    # Construct K33
    new_colors = colors[:]
    for i in range(16):
        new_colors.append(sol_c1[i])
    for i in range(16):
        new_colors.append(sol_c2[i])

    return {'n': 33, 'colors': new_colors}
